/**
 * The bundled, ready-to-run interactive activities in the library, spread across all 16
 * developmental domains. A teacher opens one to understand exactly what it teaches and
 * how to run it (objective + step-by-step instructions + materials), then assigns it to
 * a class as-is, the same way they'd assign anything they built themselves. No authoring
 * required, and — like the curriculum and shop catalog — no network round trip to browse it.
 *
 * Ten domains (Cognitive Development, Early Practical Life, Art & Craft, English, Math,
 * STEAM, Stories, Comprehension, CVC Words, Two-letter Words) still carry their original
 * 5 illustrative entries each. The other six domains (Emotional Skills, Language
 * Development, Science (EVS), Social Skills, Gross Motor, Fine Motor) carry real curriculum
 * content transcribed from the program's source lesson plans, split across small `...Real*`
 * helper functions purely to stay under the JVM's 64KB-per-method bytecode limit — a single
 * `listOf(...)` with this many entries would fail to compile otherwise.
 */
object ActivityLibrary {

