    private fun emotionalSkillsReal1(): List<LibraryActivity> = listOf(
            LibraryActivity("emo-r001", "Puzzle Play", EMOTIONAL_SKILLS, PREKG, CRAFT,
                "Improve problem-solving, teamwork, and focus by completing different types of puzzles.",
                "Introduce the idea of solving a puzzle, then split the class into three rotating stations - jigsaw puzzles, 3D building puzzles, and logic/matching puzzles - spending about 8 minutes at each before switching. Close by reflecting together on what worked, what was tricky, and how solving the puzzles felt, then review the teamwork and focus they practiced.",
                listOf("Jigsaw puzzles (easy to medium difficulty)", "3D building puzzles", "Simple logic puzzles (matching cards or patterns)", "Timer"), 45, 15),
            LibraryActivity("emo-r002", "Sorting and Categorizing", EMOTIONAL_SKILLS, LKG, CREATIVE,
                "Learn to sort and group items based on characteristics like color, size, or shape.",
                "After discussing what sorting means and demonstrating it with a set of blocks, divide children into small groups to sort a mixed set of items by color, size, or shape on sorting mats, then give each child a smaller set to sort independently. Wrap up by asking a few children to explain how they sorted their items and why.",
                listOf("Mixed objects: balls, blocks, buttons, toy animals, or pictures", "Sorting mats or trays", "Timer"), 45, 15),
            LibraryActivity("emo-r003", "What Happens Next?", EMOTIONAL_SKILLS, UKG, READING,
                "Build creative and logical thinking by guessing what happens next in a story while learning about emotions.",
                "Show a picture from a book at a cliffhanger moment and ask what might happen next, then split into small groups and give each an emotional-moment picture to discuss what happens next and how the character feels. Regroup to share guesses as a class, then reflect on how they guessed and how the character's feelings changed.",
                listOf("Picture books or cards with emotional scenes", "Paper and pencils for group work", "Whiteboard and markers"), 40, 15),
            LibraryActivity("emo-r004", "Building Challenges", EMOTIONAL_SKILLS, PREKG, CRAFT,
                "Explore how to build strong, stable structures and learn to handle challenges and emotions along the way.",
                "After discussing what makes a tower strong and demonstrating a simple structure, split children into groups of 3-4 to build a tall, strong structure from blocks, cups, or cardboard and test it by gently pushing or adding weight. Finish by discussing how it felt when their structure stood or fell and what they learned about handling that challenge.",
                listOf("Building blocks (wooden or plastic)", "Cardboard boxes", "Plastic cups", "Small weights (books or bags)", "Chart paper and markers"), 45, 15),
            LibraryActivity("emo-r005", "Cause and Effect", EMOTIONAL_SKILLS, LKG, PHYSICAL,
                "Explore cause and effect by filling beakers with water and rolling balls down ramps to observe what happens.",
                "Demonstrate how water levels change in a beaker and how far a ball rolls down a ramp, framing each as a cause leading to an effect. In small groups, children fill beakers and roll balls down ramps themselves, then share what they noticed and discuss how actions led to results.",
                listOf("Beakers", "Water", "Balls", "Ramps", "Paper and pencils"), 35, 15),
            LibraryActivity("emo-r006", "I Spy Game", EMOTIONAL_SKILLS, UKG, CREATIVE,
                "Practice asking questions and using clues to guess objects during a game of \"I Spy.\"",
