                listOf("Classroom objects (book, ball, chair, etc.)", "Flashcards or pictures for extra help"), 35, 15),
            LibraryActivity("emo-r007", "Problem Solving Scenarios", EMOTIONAL_SKILLS, PREKG, SCREEN_FREE,
                "Practice solving simple everyday problems together as a group.",
                "Show a problem card, such as two friends wanting the same toy, and explain that groups will find a solution to a similar problem. In small groups of 3-4, children discuss and agree on a solution to their own problem card, then share their solutions with the class for cheers and praise.",
