                listOf("Paper and pencils for maps", "Small treasures (stickers, toys, etc.)", "Space for the hunt"), 45, 15),
            LibraryActivity("emo-r009", "Mystery Bag Activity", EMOTIONAL_SKILLS, UKG, CRAFT,
