            LibraryActivity("emo-r017", "Picture Puzzles", EMOTIONAL_SKILLS, LKG, SCREEN_FREE,
                "Develop critical thinking and problem-solving skills through picture puzzles.",
                "Demonstrate finding corners and edges first on a simple large-piece puzzle, then pair children up to complete their own puzzle together, offering hints like matching colors or shapes to pairs who need support. Once finished, pairs show their work and explain how they solved it before the class reflects on teamwork and persistence.",
                listOf("Pre-cut picture puzzles with large pieces", "Completed puzzle for demonstration", "Reference image of the puzzle"), 45, 15),
            LibraryActivity("emo-r018", "Guess the Animal", EMOTIONAL_SKILLS, UKG, CREATIVE,
                "Practice reasoning and deduction by using clues to guess different animals.",
                "Introduce \"clue\" and \"deduction\" with an example like stripes, Africa, and grass leading to \"zebra,\" then divide the class into small groups to describe an assigned animal using clues without naming it. A few children share their own clues with the whole group to guess, then the class reflects on what helped them guess and reviews the key vocabulary.",
                listOf("Optional animal picture cards for inspiration", "Whiteboard to write vocabulary and track guesses", "Clue cards"), 45, 15),
            LibraryActivity("emo-r019", "Build a Path Lesson Plan", EMOTIONAL_SKILLS, PREKG, CRAFT,
                "Practice planning and sequencing skills by constructing a path using blocks and other materials.",
                "After discussing what a path is and demonstrating a simple block sequence, children draw their planned path on paper before gathering materials to build it, adapting their plan as needed while a teacher asks guiding sequencing questions. Close with each child showing their finished path and explaining how they designed it.",
                listOf("Assorted blocks (wooden or plastic)", "Legos or other building toys", "Paper and crayons for planning", "Pictures of paths for reference"), 45, 15),
            LibraryActivity("emo-r020", "Build a Path", EMOTIONAL_SKILLS, LKG, CRAFT,
                "Practice planning and building by creating a path for a toy car or animal.",
                "Talk about paths and demonstrate building a simple one with blocks or Legos, testing it with a toy car. In groups of 3-4, children plan, build, and test their own path with a toy car or animal, then show and describe their finished path to the class.",
                listOf("Blocks or Legos", "Toy cars or animals", "Pictures of paths", "Paper and crayons (optional)"), 45, 15),
            LibraryActivity("emo-r021", "Rhyming Games", EMOTIONAL_SKILLS, UKG, READING,
                "Improve listening and pattern recognition by identifying and creating rhyming words.",
                "Introduce rhyming with simple examples like \"cat and hat,\" then sing and clap along to a nursery rhyme, spotting its rhyming words. Play a listening game where children think of words that rhyme with a given word, then a rhyming-basket game where each child names a rhyme for an object they pick, before reflecting on their favorite rhyming word.",
                listOf("Nursery rhyme music", "Flashcards or pictures of rhyming words", "A basket with small objects or picture cards"), 40, 15),
            LibraryActivity("emo-r022", "Memory Tray Game", EMOTIONAL_SKILLS, PREKG, CREATIVE,
                "Practice memory and focus skills in a fun guessing game.",
                "Demonstrate the game by placing objects on a tray, letting children look for a minute, covering it, removing one object, and asking what's missing. Small groups then take turns looking at their own tray and guessing the missing object as it's removed, before reflecting on what helped them remember.",
                listOf("A tray", "5-7 small objects (toys, everyday items, etc.)", "A cloth to cover the tray"), 40, 15),
            LibraryActivity("emo-r023", "Stack and Count", EMOTIONAL_SKILLS, LKG, PHYSICAL,
                "Practice counting, balancing, and building skills using blocks.",
                "Demonstrate stacking blocks while counting them aloud and explaining the importance of balance, then give each child their own set of blocks to stack and count as tall as they can, seeing who can build the tallest steady tower. Finish by discussing how tall each tower was and what was hard about balancing.",
                listOf("Blocks (different sizes and shapes)", "Floor space for building", "Optional number charts for counting"), 45, 15),
            LibraryActivity("emo-r024", "Animal Actions", EMOTIONAL_SKILLS, UKG, PHYSICAL,
                "Build creativity and decision-making by acting out different animal movements.",
                "Demonstrate a few animal movements like hopping like a frog or stomping like an elephant, then call out animals for children to act out, letting them suggest their own too. Set up a simple obstacle course so children can navigate it moving like different animals, then reflect on their favorite animal to act out and how the movement felt.",
                listOf("Pictures of animals", "Cones or ropes for the obstacle course", "Open space to move", "Music (optional)"), 40, 15),
            LibraryActivity("emo-r025", "Cooking Together: Making Sandwiches", EMOTIONAL_SKILLS, PREKG, CRAFT,
                "Practice sequencing and measuring skills while preparing a simple snack.",
                "Introduce the ideas of sequencing and measuring, then demonstrate making a sandwich step by step - laying out bread, spreading, adding fillings, closing, and cutting it. In small groups with assigned roles, children make their own sandwiches with adult help measuring spreads, then share what they liked and found tricky about following the steps.",
                listOf("Bread", "Spreads (butter, mayo, etc.)", "Fillings (cheese, ham, lettuce, etc.)", "Child-safe knives", "Chopping boards", "Measuring spoons"), 45, 15),
            LibraryActivity("emo-r026", "Number Hunt Activity", EMOTIONAL_SKILLS, LKG, SCREEN_FREE,
                "Identify letters and numbers in an exciting, interactive hunt.",
                "Explain the difference between letters and numbers and demonstrate identifying a hidden card, then let pairs or small groups search the room for hidden letter and number cards, calling out each one as they find it. Regroup to have each pair show a card they found and discuss its shape or sound.",
                listOf("Letter cards (A-Z)", "Number cards (0-10)", "Small bags or envelopes to carry cards", "Timer or bell to start and stop the game"), 45, 15),
            LibraryActivity("emo-r027", "Build a Bridge Activity", EMOTIONAL_SKILLS, UKG, CRAFT,
                "Practice problem-solving and engineering skills by designing and building a bridge that can hold a small toy car or animal.",
                "Show pictures of real bridges and discuss what makes one strong, then in groups of three children plan and build their own bridge from blocks, craft sticks, and Legos to make it stable. Test each bridge with a small toy car or animal to see if it holds, then reflect as a class on what worked and what they'd change.",
                listOf("Building blocks", "Craft sticks", "Legos", "Toy cars or animals", "Optional tape, glue, or string", "Pictures of real bridges"), 45, 15),
            LibraryActivity("emo-r028", "Ice Cube Melt Activity", EMOTIONAL_SKILLS, PREKG, CREATIVE,
                "Learn about how ice melts and what makes it melt faster.",
                "After discussing what happens to ice outside the freezer, give each child an ice cube and challenge them to find ways to make it melt faster using warm water, blowing through a straw, or holding it. Share what worked best as a group and explain simply why warm water melted the ice fastest.",
                listOf("Ice cubes (one for each child)", "Bowls of warm water", "Towels", "Straws"), 40, 15),
            LibraryActivity("emo-r029", "Sorting by Texture", EMOTIONAL_SKILLS, LKG, CREATIVE,
                "Use touch to explore and sort objects by how they feel.",
                "Talk about textures like smooth, soft, and rough using clothing or classroom objects, then demonstrate sorting a few items out loud by feel. In small groups, children sort a tray of textured items - rocks, sponges, fabrics - by how they feel, then share their sorted groups and describe the textures.",
                listOf("Smooth rocks, rough sponges, soft fabrics", "Sorting trays or mats"), 45, 15),
            LibraryActivity("emo-r030", "Hide and Seek Shapes", EMOTIONAL_SKILLS, UKG, READING,
                "Find and name shapes while working together as a group.",
                "Review the shapes and explain the game by hiding one and pretending to find it, then hide the paper shapes around the room in spots like shelves and behind books. Children search for the shapes, naming and describing each one they find, before the group discusses teamwork and what shapes they found.",
                listOf("Paper shapes: circles, squares, triangles, rectangles", "A classroom with fun hiding spots"), 40, 15),
            LibraryActivity("emo-r031", "Pattern Blocks", EMOTIONAL_SKILLS, PREKG, SCREEN_FREE,
                "Learn about patterns, shapes, and creating designs.",
                "Talk about where patterns appear (like stripes or leaves), then demonstrate a simple block pattern before children try copying the pattern shown on a card, working with a buddy if needed. Finish by letting children create their own original pattern designs and share what shapes they used.",
                listOf("Pattern blocks (triangles, squares, circles)", "Pattern cards with simple designs"), 45, 15),
            LibraryActivity("emo-r032", "Make a Prediction", EMOTIONAL_SKILLS, LKG, READING,
                "Practice guessing what might happen next through fun, simple activities.",
                "Explain that a guess is thinking about what might happen, using a dropped ball as an example, then read a short story and pause to predict what happens next. In small groups, children predict and test simple results - pouring water on sand, mixing two paints, and mixing vinegar with baking soda - before sharing what they guessed and what actually happened.",
                listOf("Sand and water", "Paint and paper", "Baking soda and vinegar", "A simple storybook"), 35, 15),
            LibraryActivity("emo-r033", "Simon Says", EMOTIONAL_SKILLS, UKG, PHYSICAL,
                "Improve listening and following directions by playing \"Simon Says.\"",
                "Explain that children should only follow an instruction when it's preceded by \"Simon says,\" then warm up with a few fun movements before leading a full round of the game, occasionally trying to trick them by dropping the phrase. Wrap up by asking what was fun and what made it hard to follow directions.",
                listOf(), 35, 15),
            LibraryActivity("emo-r034", "Match the Lids", EMOTIONAL_SKILLS, PREKG, SCREEN_FREE,
                "Practice matching lids to containers to build problem-solving and fine motor skills.",
                "Demonstrate how a lid's shape and size determine which container it fits, then let small groups work together to match a mixed set of containers and lids before children try matching independently. Reflect together on what was easy and what was tricky about finding the right match.",
                listOf("Containers and lids (different shapes and sizes)", "A table or mat for play"), 35, 15),
            LibraryActivity("emo-r035", "Rainbow Colour Hunt", EMOTIONAL_SKILLS, LKG, SCREEN_FREE,
                "Learn and recognize rainbow colors by finding and sorting matching objects.",
                "Show a rainbow picture and teach the colors with flashcards, then send children around the room to quietly collect objects matching each rainbow color into their bag. Sort the found items together by color on a large poster and let each child share one of their finds.",
                listOf("Rainbow picture or poster", "Flashcards of rainbow colours", "Bags/containers for collecting items"), 33, 15),
    )

    private fun emotionalSkillsReal2(): List<LibraryActivity> = listOf(
            LibraryActivity("emo-r036", "Follow the Map", EMOTIONAL_SKILLS, UKG, PHYSICAL,
                "Learn to follow directions and use a simple map to find a hidden treasure.",
                "Show a simple map of the room and demonstrate walking it to a hidden treasure, pointing out how symbols match real places. In small groups, children follow their own map and clues to find hidden treasures, then reflect on whether the map was easy to follow and celebrate their success.",
                listOf("Simple maps (one for each group)", "Small treasures (stickers, toys)", "Symbols or pictures for the map"), 35, 15),
            LibraryActivity("emo-r037", "Shape Towers", EMOTIONAL_SKILLS, PREKG, PHYSICAL,
                "Learn about shapes, balance, and stacking by building towers with blocks.",
                "Demonstrate building a simple tower and explain how a wide base keeps it stable, then let small groups build towers together before children build their own independently, thinking about balance and sturdy shapes at the bottom. Gather to admire the towers and discuss what worked well and what was tricky.",
                listOf("Blocks in different shapes (cubes, cylinders, pyramids)", "Space to build safely"), 35, 15),
            LibraryActivity("emo-r038", "What Doesn't Belong?", EMOTIONAL_SKILLS, LKG, SCREEN_FREE,
                "Learn to group items and identify the one that doesn't fit.",
                "Show an example set like three apples and one toy and ask which doesn't belong and why, then give small groups their own set of items with an odd one out to find and explain. Children then circle the odd one out on an individual worksheet, and the class reflects on what they learned about grouping.",
                listOf("Sets of items (real objects or pictures)", "Worksheets with simple groups of pictures", "Crayons or markers"), 40, 15),
            LibraryActivity("emo-r039", "Create a Story", EMOTIONAL_SKILLS, UKG, CRAFT,
                "Use creativity to build simple stories based on pictures.",
                "Discuss what makes a story - characters, setting, and events - using a picture as a prompt, then split into small groups and give each a picture to build a story from by answering who, where, and what happens first, next, and last. Each group tells their story to the class, and the class discusses their favorite parts.",
                listOf("Pictures for stories", "Paper and markers for drawing or writing", "Optional storybooks for examples"), 45, 15),
            LibraryActivity("emo-r040", "Sorting Buttons or Beads", EMOTIONAL_SKILLS, PREKG, CRAFT,
                "Practice sorting while improving fine motor skills.",
                "Discuss what sorting means and demonstrate sorting a few buttons or beads by color, shape, or size, then give each group their own set to sort by a rule of their choosing, offering guiding questions to children who need support. Gather to talk about how each group sorted their items and praise their fine motor effort.",
                listOf("Buttons/beads (different sizes, shapes, colours)", "Trays or small containers"), 45, 15),
            LibraryActivity("emo-r041", "Opposite Hunt", EMOTIONAL_SKILLS, LKG, CREATIVE,
                "Learn the concept of opposites and encourage logical thinking through a fun hunt.",
                "Introduce opposites with examples like big/small and hot/cold, then explain that when a word is called out, children must find or act out its opposite. Call out words like \"big\" or \"hot\" for children to respond to around the room, then gather to share what they found or acted out and why those words are opposites.",
                listOf("Pictures or flashcards showing opposites", "Small objects (e.g., big/small balls)", "Open space for moving around"), 45, 15),
            LibraryActivity("emo-r042", "Maze Fun", EMOTIONAL_SKILLS, UKG, CRAFT,
                "Practice planning and thinking by creating and solving mazes.",
                "Show pictures of mazes and discuss how to help a toy get through one, then in small groups children plan and build their own maze on paper or with blocks, including turns and obstacles. They test it by guiding a toy through their maze and discussing their choices, then share their finished mazes and celebrate the creativity.",
                listOf("Maze pictures to show", "Paper and markers", "Blocks for building", "Toys to navigate the maze"), 45, 15),
    )

    private fun languageDevelopmentReal1(): List<LibraryActivity> = listOf(
            LibraryActivity("lang-r001", "Story Time and Retelling", LANGUAGE_DEVELOPMENT, PREKG, READING,
                "Enhance vocabulary, comprehension, and narrative skills.",
                "Read a simple story aloud to the children. After reading, ask the children to retell the story in their own words, prompting them with questions like, “What happened first?” or “How did the story end?” Encourage them to use their imagination and expand on the story.",
                listOf(), 20, 15),
            LibraryActivity("lang-r002", "Sing Songs and Rhymes", LANGUAGE_DEVELOPMENT, LKG, READING,
                "Improve phonemic awareness and memory.",
                "Sing songs with repetitive lyrics and rhymes, such as “Twinkle, Twinkle Little Star” or “The Wheels on the Bus.” Ask the children to repeat after you, then encourage them to sing along. Play games with rhyming words, like finding words that rhyme with “cat,” “hat,” etc.",
                listOf(), 20, 15),
            LibraryActivity("lang-r003", "Show and Tell", LANGUAGE_DEVELOPMENT, UKG, SCREEN_FREE,
                "Encourage verbal expression, listening, and vocabulary development.",
                "Ask each child to bring an item from home or pick something from the classroom to talk about. Encourage them to describe the item (color, size, shape) and explain why they chose it. Ask open-ended questions like, “Can you tell me more about this?” or “How does it work?”",
                listOf(), 20, 15),
            LibraryActivity("lang-r004", "Matching Sounds", LANGUAGE_DEVELOPMENT, PREKG, SCREEN_FREE,
                "Develop listening and phonological awareness.",
                "Gather objects or pictures that start with the same sound (e.g., apple, ant, alligator for the “A” sound). Ask the children to listen and match the objects to the correct sound or letter. This can be expanded by asking children to come up with their own examples of words that begin with certain sounds.",
                listOf(), 20, 15),
            LibraryActivity("lang-r005", "Interactive Reading with Puppets", LANGUAGE_DEVELOPMENT, LKG, READING,
                "Develop social language skills and imagination.",
                "Use puppets or stuffed animals to act out parts of a story. Engage children by asking them questions or allowing them to take turns as the puppet. Ask the children to act out simple scenarios with the puppets, helping them practice dialogue and different expressions.",
                listOf(), 20, 15),
            LibraryActivity("lang-r006", "Building Sentences with Blocks", LANGUAGE_DEVELOPMENT, UKG, PHYSICAL,
                "Strengthen grammar and sentence structure.",
                "Provide children with blocks or cards with pictures or words on them (e.g., “cat,” “run,” “big,” “happy”). Ask them to build simple sentences by arranging the blocks in order (e.g., “The cat runs.”). Encourage them to create their own sentences with the blocks, using basic grammar structures.",
                listOf(), 20, 15),
            LibraryActivity("lang-r007", "Picture Walks", LANGUAGE_DEVELOPMENT, PREKG, READING,
                "Expand vocabulary and storytelling skills.",
                "Show the children a picture book but don’t read the words yet. Ask them to look at the pictures and describe what they see. Encourage them to make up their own story based on the pictures, helping them use more descriptive language.",
                listOf(), 20, 15),
            LibraryActivity("lang-r008", "Conversation Circles", LANGUAGE_DEVELOPMENT, LKG, SCREEN_FREE,
                "Practice listening and taking turns in conversation.",
                "Gather the children in a circle and start a simple conversation (e.g., “What is your favorite color?” or “What did you do this morning?”). Encourage each child to answer and ask questions of their own, fostering back-and-forth communication. Support shy or hesitant children by gently prompting them.",
                listOf(), 20, 15),
            LibraryActivity("lang-r009", "Rhyme Time with Flashcards", LANGUAGE_DEVELOPMENT, UKG, READING,
                "Strengthen rhyming skills and phonetic awareness.",
                "Show a flashcard with a picture (e.g., a \"dog\"). Ask the children to think of other words that rhyme with the picture (e.g., \"log,\" \"frog\"). You can play this as a group game, where children take turns suggesting rhyming words.",
                listOf(), 20, 15),
            LibraryActivity("lang-r010", "Listening Games", LANGUAGE_DEVELOPMENT, PREKG, SCREEN_FREE,
                "Improve auditory discrimination and listening skills.",
                "Play a game where children close their eyes and listen to various sounds (e.g., animal noises, instruments, or everyday sounds). Ask them to guess the sound and describe it. You can also ask them to identify objects that make the same sound or use these sounds in stories.",
                listOf(), 20, 15),
            LibraryActivity("lang-r011", "Animal Sound Game", LANGUAGE_DEVELOPMENT, LKG, SCREEN_FREE,
                "Enhance listening skills and help with language development.",
                "Make different animal sounds (e.g., \"moo\" for a cow, \"baa\" for a sheep, \"roar\" for a lion) and encourage your child to imitate them. Show them pictures or toys of the animals while making the sounds. Ask, \"What sound does a cow make?\" to prompt them to respond. You can also ask them to point to the correct animal.",
                listOf(), 20, 15),
            LibraryActivity("lang-r012", "Simple Songs with Actions", LANGUAGE_DEVELOPMENT, UKG, CREATIVE,
                "Improve memory, vocabulary, and coordination.",
                "Sing songs with simple lyrics and hand motions, like “If You’re Happy and You Know It” or “Head, Shoulders, Knees, and Toes.” Encourage your child to sing along and do the actions. This reinforces vocabulary and helps develop their listening skills.",
                listOf(), 20, 15),
            LibraryActivity("lang-r013", "Naming Everyday Objects", LANGUAGE_DEVELOPMENT, PREKG, READING,
                "Build vocabulary and cognitive skills.",
                "Point to objects around the house (e.g., cup, shoe, ball, book) and say their names. Encourage your child to repeat the names after you. You can also ask, “Where is your cup?” and help them identify it. Over time, ask your child to name the objects themselves.",
                listOf(), 20, 15),
            LibraryActivity("lang-r014", "Picture Book Exploration", LANGUAGE_DEVELOPMENT, LKG, READING,
                "Develop vocabulary and storytelling skills.",
                "Look at simple picture books with your child. Point to different images and name them aloud (e.g., “This is a dog” or “Look, a red ball!”). Ask questions like, “What do you see?” and encourage your child to point to objects as they identify them.",
                listOf(), 20, 15),
            LibraryActivity("lang-r015", "Interactive Play with Blocks", LANGUAGE_DEVELOPMENT, UKG, CRAFT,
                "Strengthen communication skills through play.",
                "Use blocks to build simple structures together. While building, name the colors, shapes, and sizes of the blocks. Encourage your child to say phrases like “big block” or “yellow block” as they play. You can also count the blocks together.",
                listOf(), 20, 15),
            LibraryActivity("lang-r016", "Follow the Leader", LANGUAGE_DEVELOPMENT, PREKG, PHYSICAL,
                "Promote listening skills and understanding simple instructions.",
                "Play a simple “Follow the Leader” game where you do actions (e.g., clapping, stomping, jumping) and ask your child to follow. Give simple instructions like, “Clap your hands!” or “Jump!” Encourage them to repeat the actions and, over time, the phrases as well.",
                listOf(), 20, 15),
            LibraryActivity("lang-r017", "Sensory Language Play", LANGUAGE_DEVELOPMENT, LKG, CRAFT,
                "Help children connect words to their senses (sight, touch, smell, etc.).",
                "Use sensory bins filled with different textures like rice, sand, or fabric. Encourage your child to describe what they feel (e.g., “soft,” “rough,” “bumpy”) and name objects they find in the bin. This helps them build vocabulary and connects sensory experiences to language.",
                listOf(), 20, 15),
            LibraryActivity("lang-r018", "Coloring and Talking About Colors", LANGUAGE_DEVELOPMENT, UKG, CRAFT,
                "Build vocabulary around colors and develop fine motor skills.",
                "Give your child crayons or markers and encourage them to color a picture. As they color, ask them to name the colors they are using. You can prompt with questions like, “What color is the sky?” or “Can you color the sun yellow?” This helps them connect colors to words.",
                listOf(), 20, 15),
            LibraryActivity("lang-r019", "Pretend Play with Dolls or Stuffed Animals", LANGUAGE_DEVELOPMENT, PREKG, CREATIVE,
                "Encourage imaginative play and language use.",
                "Play with dolls or stuffed animals together. Create simple scenarios, like feeding the doll or putting it to bed, and use language to describe the actions. Encourage your child to talk to the dolls or animals and mimic your words.",
                listOf(), 20, 15),
            LibraryActivity("lang-r020", "Interactive Sorting Game", LANGUAGE_DEVELOPMENT, LKG, SCREEN_FREE,
                "Develop categorization skills and build vocabulary.",
                "Provide simple objects of different colors or shapes (e.g., blocks, buttons, or toys). Encourage your child to sort them into categories (e.g., \"Red block\" or \"Big toy\"). Talk about what they are doing to reinforce the language around categories (e.g., \"The blue one goes here\").",
                listOf(), 20, 15),
            LibraryActivity("lang-r021", "Simple “Yes/No” Questions", LANGUAGE_DEVELOPMENT, UKG, SCREEN_FREE,
                "Develop the ability to understand and answer questions.",
                "Ask your child simple yes/no questions, such as, “Do you want a snack?” or “Is this your ball?” Encourage them to respond, either with “yes” or “no.” As they become more confident, introduce additional simple questions (e.g., “Do you like the red car?”).",
                listOf(), 20, 15),
            LibraryActivity("lang-r022", "Action Words Game", LANGUAGE_DEVELOPMENT, PREKG, PHYSICAL,
                "Teach verbs and improve listening and comprehension.",
                "Say simple action words (e.g., “run,” “jump,” “clap”) and encourage your child to act them out. After a few rounds, ask your child to tell you what action they want to do, and you can follow along.",
                listOf(), 15, 10),
            LibraryActivity("lang-r023", "Rhyming Game", LANGUAGE_DEVELOPMENT, LKG, READING,
                "Help children develop phonological awareness by recognizing rhyming words.",
                "Say a word (e.g., “cat”) and ask your child to come up with a word that rhymes (e.g., “hat”). You can also play with objects or toys that rhyme (e.g., “dog” and “log”) to make it interactive. Encourage your child to repeat the words after you to strengthen memory and language patterns.",
                listOf(), 20, 15),
            LibraryActivity("lang-r024", "Simple Direction Following", LANGUAGE_DEVELOPMENT, UKG, SCREEN_FREE,
                "Improve comprehension of simple instructions.",
                "Give your child simple instructions to follow, such as “Pick up the ball” or “Put the cup on the table.” Gradually make the instructions a little more complex by adding two steps (e.g., “Pick up the ball and give it to mommy”). Praise your child when they follow the directions correctly to reinforce their understanding.",
                listOf(), 20, 15),
            LibraryActivity("lang-r025", "Name the Parts of the Body", LANGUAGE_DEVELOPMENT, PREKG, SCREEN_FREE,
                "Help your child learn and remember body parts.",
                "Point to different body parts (e.g., head, shoulders, knees, toes) and name them. Ask your child to touch the body part as you say the word aloud (e.g., “Touch your head”). Play a game by asking, “Where’s your nose?” or “Where’s your elbow?”",
                listOf(), 20, 15),
            LibraryActivity("lang-r026", "Flashcard Fun", LANGUAGE_DEVELOPMENT, LKG, SCREEN_FREE,
                "Build vocabulary through visual learning.",
                "Use flashcards with simple pictures (animals, objects, foods) and name them together. Show the card to your child and ask them to repeat the word. To make it more interactive, you can ask questions like, “Can you find the cat?” or “What color is the apple?”",
                listOf(), 20, 15),
            LibraryActivity("lang-r027", "Interactive Sensory Bins", LANGUAGE_DEVELOPMENT, UKG, SCREEN_FREE,
                "Encourage language through sensory exploration.",
                "Fill a bin with rice, beans, or sand, and add small toys or objects like animals, shapes, or food items. As your child digs and explores, ask them to describe what they find (e.g., “What is this?” or “Can you feel the soft teddy bear?”). Encourage your child to use their own words, guiding them to expand their vocabulary.",
                listOf(), 20, 15),
            LibraryActivity("lang-r028", "Family Picture Book", LANGUAGE_DEVELOPMENT, PREKG, READING,
                "Develop narrative skills and expand vocabulary.",
                "Create a simple picture book with photos of family members or favorite objects. As you look at the pictures together, ask your child to tell a simple story or talk about the people or objects. This helps your child connect words with real-life experiences.",
                listOf(), 20, 15),
            LibraryActivity("lang-r029", "Treasure Hunt", LANGUAGE_DEVELOPMENT, LKG, CREATIVE,
                "Improve understanding of prepositions and vocabulary.",
                "Hide a few toys or objects around the room or house and give your child clues using prepositions (e.g., “under the table,” “next to the chair”). Encourage your child to search for the items by following the instructions. Ask them to describe where they found the item (e.g., “I found it under the couch”).",
                listOf(), 20, 15),
            LibraryActivity("lang-r030", "Cooking Together", LANGUAGE_DEVELOPMENT, UKG, CRAFT,
                "Build vocabulary and understanding of sequencing.",
                "Involve your child in a simple kitchen task, like making a sandwich or stirring ingredients. As you go through the steps, say the actions aloud (e.g., “Spread the butter,” “Cut the bread”). Ask questions like, “What should we do next?” or “Can you pass me the spoon?”",
                listOf(), 20, 15),
            LibraryActivity("lang-r031", "Dress Up and Role Play", LANGUAGE_DEVELOPMENT, PREKG, CREATIVE,
                "Encourage creative language use and expression.",
                "Use dress-up clothes or props for your child to pretend to be different characters (e.g., a doctor, chef, or animal). Encourage your child to use language to describe what they’re doing (e.g., “I’m cooking,” “I’m fixing the car”). Role-play simple conversations, such as a doctor talking to a patient, to encourage sentence formation.",
                listOf(), 20, 15),
            LibraryActivity("lang-r032", "Color Sorting Game", LANGUAGE_DEVELOPMENT, LKG, SCREEN_FREE,
                "Help your child learn colors and practice sorting.",
                "Provide a selection of colored objects (e.g., colored blocks, buttons, or balls) and ask your child to sort them by color. As they sort, say the color names aloud and ask them to repeat (e.g., “Red block,” “Blue ball”). For added complexity, ask them to group the objects by shape or size, reinforcing new vocabulary.",
                listOf(), 20, 15),
            LibraryActivity("lang-r033", "Simple Puzzle Play", LANGUAGE_DEVELOPMENT, UKG, SCREEN_FREE,
                "Enhance problem-solving skills and build vocabulary.",
                "Use simple puzzles with pictures of animals, vehicles, or other familiar objects. While assembling the puzzle, name the pieces (e.g., “Here’s the dog” or “That’s the truck”). Encourage your child to talk about the puzzle pieces, reinforcing their understanding of words and categories.",
