    fun forDomain(domain: DevelopmentalDomain): List<LibraryActivity> = all.filter { it.domain == domain }

    fun forGrade(grade: Grade): List<LibraryActivity> = all.filter { it.grade == grade }

    fun forDomainAndGrade(domain: DevelopmentalDomain, grade: Grade): List<LibraryActivity> =
        all.filter { it.domain == domain && it.grade == grade }

    fun byId(id: String): LibraryActivity? = all.firstOrNull { it.id == id }
}

